{
  "id": "V029",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "영어 독자에게 기업 소식을 전달하려는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "한국어 기사를 영어로 번역하고 원문과 대조 검토하는 흐름이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "국내에서 작성한 기업 소식 기사가 대상임."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어로 작성된 국내 기업 소식 기사 내용이 명시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 번역문이 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "원문에 없는 인용이나 성과를 추가하지 않는 제약이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가했다고 볼 근거가 없음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "배포 담당자의 누락 재확인과 편집자의 검토·게시 결정 역할이 구분됨."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "고유명사와 수치가 빠지지 않았는지",
      "view_quote": "",
      "reason": "세 뷰 모두 원문에서 고유명사와 수치 누락 여부를 확인한다는 사항을 명시하지 않음."
    }
  ],
  "permission_interpretation": "게시 여부는 편집자가 결정한다고 보존됨. 이는 AI가 게시하거나 편집자가 매번 실제로 게시한다는 뜻으로 해석하지 않음."
}
